const detailedPlan = $('Create Detailed Plan (Groq)1').first().json.choices[0].message.content;
const aggregateData = $('Aggregate Research1').first().json;
const citations = aggregateData.citations;

let result = detailedPlan;
const citationPattern = /\[(\d+)\]/g;

result = result.replace(citationPattern, (match, num) => {
  const index = parseInt(num) - 1;
  if (index >= 0 && index < citations.length) {
    return `(${citations[index]})`;
  }
  return match;
});

return [{ 
  json: { 
    detailedPlan: result,
    keywords: aggregateData.keywords,
    intent: aggregateData.intent,
    primaryKeyword: aggregateData.primaryKeyword,
    rowNumber: aggregateData.rowNumber
  } 
}];

