// Parse unified metadata response
const response = $input.first().json.choices[0].message.content;
let metadata;

try {
  // Remove markdown code blocks if present
  const cleaned = response.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  metadata = JSON.parse(cleaned);
} catch (error) {
  // Fallback: try to extract JSON from text
  const jsonMatch = response.match(/\{[\s\S]*\}/);
  if (jsonMatch) {
    metadata = JSON.parse(jsonMatch[0]);
  } else {
    throw new Error('Failed to parse metadata JSON: ' + error.message);
  }
}

// Get original data
const blogData = $('Merge Blog Versions1').first().json;

return [{
  json: {
    slug: metadata.slug || '',
    title: metadata.title || '',
    metaDescription: metadata.metaDescription || '',
    finalBlogText: blogData.finalBlogText,
    keywords: blogData.keywords,
    primaryKeyword: blogData.primaryKeyword,
    rowNumber: blogData.rowNumber
  }
}];

